function profileColor(profile){let value=0;for(const char of profile.id)value=(value*31+char.charCodeAt(0))>>>0;return colors[value%colors.length]}
function profileAge(dateOfBirth){if(!dateOfBirth)return null;const[year,month,day]=dateOfBirth.split('-').map(Number),today=new Date();let age=today.getFullYear()-year;if(today.getMonth()+1<month||(today.getMonth()+1===month&&today.getDate()<day))age--;return age>=0?age:null}
function localDateInputValue(){const today=new Date(),offset=today.getTimezoneOffset()*60000;return new Date(today.getTime()-offset).toISOString().slice(0,10)}
function birthdayToday(dateOfBirth){if(!dateOfBirth)return false;const[,month,day]=dateOfBirth.split('-').map(Number),today=new Date();return today.getMonth()+1===month&&today.getDate()===day}
function birthdayAvailable(dateOfBirth){return birthdayToday(dateOfBirth)}
function profilePicture(name){return `${import.meta.env.BASE_URL}profiles/${encodeURIComponent(legacyProfilePictures[name]||name)}`}
function mediaCrossOrigin(url){try{return new URL(url).hostname.endsWith('.backblazeb2.com')?'anonymous':undefined}catch{return undefined}}
function finishLoading(setter,startedAt){setTimeout(()=>setter(false),Math.max(0,900-(Date.now()-startedAt)))}
function Avatar({profile,add=false}){return <span className={`avatar${add?' add-avatar':''}`} style={add?undefined:{'--avatar-color':profileColor(profile)}} aria-hidden="true">{add?<FontAwesomeIcon icon={faPlus}/>:profile.avatar?<img src={profilePicture(profile.avatar)} alt=""/>:<FontAwesomeIcon className="avatar-face" icon={faFaceSmile}/>}</span>}
function Logo(){return <img className="brand-logo" src={`${import.meta.env.BASE_URL}logo-kingflix.png`} alt="Kingflix"/>}
function LoadingScreen({active=true}){
  const[visible,setVisible]=useState(active)
  useEffect(()=>{
    if(active){setVisible(true);return}
    const timer=setTimeout(()=>setVisible(false),250)
    return()=>clearTimeout(timer)
  },[active])
  if(!active&&!visible)return null
  return <div className={`loading-screen${active?'':' loading-screen-exiting'}`} role="status" aria-live="polite"><Logo/><span>Loading...</span></div>
}

function App(){
  const{getToken}=useAuth()
  const[profiles,setProfiles]=useState([]),[profile,setProfile]=useState(null),[profileToken,setProfileToken]=useState('')
  const[view,setView]=useState('select'),[pending,setPending]=useState(null),[pin,setPin]=useState('')
  const[manageToken,setManageToken]=useState('')
  const[picturePicker,setPicturePicker]=useState(null)
  const[form,setForm]=useState({name:'',dateOfBirth:'',pin:'',removePin:false,homeVideosOnly:false,avatar:'bluey.png'})
  const[media,setMedia]=useState([]),[progress,setProgress]=useState([]),[favorites,setFavorites]=useState([]),[selected,setSelected]=useState(null)
  const[error,setError]=useState(''),[busy,setBusy]=useState(false),[profilesLoading,setProfilesLoading]=useState(true),[libraryLoading,setLibraryLoading]=useState(false)
  const[unlockLoading,setUnlockLoading]=useState(false)
  const[birthdayProfile,setBirthdayProfile]=useState(null)
  async function request(path,options={}){const token=await getToken();const response=await fetch(`${api}${path}`,{...options,headers:{Authorization:`Bearer ${token}`,'Content-Type':'application/json',...(profileToken?{'X-Profile-Token':profileToken}:{}),...(manageToken?{'X-Manage-Token':manageToken}:{}),...options.headers}});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||`Request failed: ${response.status}`);return data}
  async function loadLibrary(profileId){const items=[];for(let offset=0;;offset+=50){const page=await request(`/api/library?profileId=${encodeURIComponent(profileId)}&limit=50&offset=${offset}`);items.push(...page);if(page.length<50)return items}}
  const enterManage=useReverification(async()=>{const token=await getToken();const response=await fetch(`${api}/api/manage-access`,{method:'POST',headers:{Authorization:`Bearer ${token}`,'Content-Type':'application/json'}});return response.json()})
  async function updateManagedMedia(id,body){const token=await getToken();const response=await fetch(`${api}/api/manage-media/${encodeURIComponent(id)}`,{method:'POST',headers:{Authorization:`Bearer ${token}`,'Content-Type':'application/json','X-Manage-Token':manageToken},body:JSON.stringify(body)});const data=await response.json();if(!response.ok)throw new Error(data.error||'Could not save video.');return data}
  async function updateManagedSeries(id,body){const token=await getToken();const response=await fetch(`${api}/api/manage-series/${encodeURIComponent(id)}`,{method:'POST',headers:{Authorization:`Bearer ${token}`,'Content-Type':'application/json','X-Manage-Token':manageToken},body:JSON.stringify(body)});const data=await response.json();if(!response.ok)throw new Error(data.error||'Could not save series.');return data}
  const updateProfile=useReverification(async(id,body)=>{const token=await getToken();const response=await fetch(`${api}/api/profiles/${id}`,{method:'POST',headers:{Authorization:`Bearer ${token}`,'Content-Type':'application/json','X-Profile-Token':profileToken},body:JSON.stringify(body)});return response.json()})
  async function openManage(target='manage'){try{setError('');const result=await enterManage();if(result?.ok){setManageToken(result.token||'');setView(target)}}catch(e){if(e?.name!=='ClerkRuntimeError')setError(e.message||'Password verification was cancelled.')}}
  useEffect(()=>{const startedAt=Date.now();request('/api/profiles').then(setProfiles).catch(e=>setError(e.message)).finally(()=>finishLoading(setProfilesLoading,startedAt))},[])
  useEffect(()=>{if(profile&&profileToken){const startedAt=Date.now();setLibraryLoading(true);Promise.all([loadLibrary(profile.id),request(`/api/progress?profileId=${encodeURIComponent(profile.id)}`),request(`/api/favorites?profileId=${encodeURIComponent(profile.id)}`)]).then(([items,positions,saved])=>{setMedia(items);setProgress(positions);setFavorites(saved.map(item=>item.mediaId))}).catch(e=>setError(e.message)).finally(()=>finishLoading(setLibraryLoading,startedAt))}},[profile,profileToken])
  function resetForm(){setForm({name:'',dateOfBirth:'',pin:'',removePin:false,homeVideosOnly:false,avatar:'bluey.png'})}
  function begin(item,action){setError('');if(item.hasPin){setPending({profile:item,action});setPin('')}else unlock(item,'',action)}
  async function unlock(item,enteredPin,action){
    if(unlockLoading)return
    setUnlockLoading(true)
    setBusy(true)
    setError('')
    try{
      const result=await request(`/api/profiles/${item.id}/unlock`,{method:'POST',body:JSON.stringify({pin:enteredPin}),headers:{'X-Profile-Token':''}})
      setProfileToken(result.token)
      setPending(null)
      setPin('')
      setProfile(item)
      if(action==='edit'){
        setForm({name:item.name,dateOfBirth:item.dateOfBirth||'',homeVideosOnly:Boolean(item.homeVideosOnly),pin:'',removePin:false,avatar:item.avatar||'bluey.png'})
        setView('edit')
      }else{
        setLibraryLoading(true)
        setView('library')
        const birthdayKey=`kingflix-birthday-${item.id}-${localDateInputValue()}`
        if(birthdayAvailable(item.dateOfBirth)&&localStorage.getItem(birthdayKey)!=='dismissed')setBirthdayProfile(item)
      }
    }catch(e){
      await new Promise(resolve=>setTimeout(resolve,1000))
      setPin('')
      setError(e.message)
    }finally{
      setBusy(false)
      setUnlockLoading(false)
    }
  }
  async function addProfile(event){event.preventDefault();try{setBusy(true);setError('');const created=await request('/api/profiles',{method:'POST',body:JSON.stringify({name:form.name,dateOfBirth:form.dateOfBirth,homeVideosOnly:form.homeVideosOnly,pin:form.pin,avatar:form.avatar})});setProfiles(current=>[...current,created]);resetForm();setView('manage')}catch(e){setError(e.message)}finally{setBusy(false)}}
  async function saveProfile(event){event.preventDefault();try{setBusy(true);setError('');const saved=await updateProfile(profile.id,{name:form.name,dateOfBirth:form.dateOfBirth,homeVideosOnly:form.homeVideosOnly,avatar:form.avatar});if(saved?.error)throw new Error(saved.error);let hasPin=profile.hasPin;if(form.pin||form.removePin){const result=await request(`/api/profiles/${profile.id}/pin`,{method:'POST',body:JSON.stringify({pin:form.removePin?'':form.pin})});hasPin=result.hasPin}const updated={...profile,name:form.name.trim(),dateOfBirth:form.dateOfBirth,homeVideosOnly:form.homeVideosOnly,avatar:form.avatar,hasPin};setProfiles(current=>current.map(item=>item.id===profile.id?updated:item));setProfile(null);setProfileToken('');resetForm();setView('manage')}catch(e){setError(e.message||'Password verification was cancelled.')}finally{setBusy(false)}}
  async function deleteProfile(){try{setBusy(true);setError('');await request(`/api/profiles/${profile.id}`,{method:'DELETE'});setProfiles(current=>current.filter(item=>item.id!==profile.id));setProfile(null);setProfileToken('');resetForm();setView('manage')}catch(e){setError(e.message)}finally{setBusy(false)}}
  async function play(item,startAt=0){if(item.blocked)return;try{setError('');setSelected({...item,...await request(`/api/media/${item.id}/play`,{method:'POST',body:JSON.stringify({profileId:profile.id})}),startAt})}catch(e){setError(e.message)}}
  async function saveProgress(value){const currentTime=typeof value==='number'?value:value?.target?.currentTime;if(!selected||!profile||!Number.isFinite(currentTime))return;const positionSeconds=Math.floor(currentTime),updatedAt=new Date().toISOString();setProgress(current=>[{mediaId:selected.id,positionSeconds,updatedAt},...current.filter(item=>item.mediaId!==selected.id)]);try{await request('/api/progress',{method:'POST',body:JSON.stringify({profileId:profile.id,mediaId:selected.id,positionSeconds})})}catch(e){setError(e.message)}}
  async function toggleFavorite(mediaId){const saved=favorites.includes(mediaId);setFavorites(current=>saved?current.filter(id=>id!==mediaId):[...current,mediaId]);try{await request('/api/favorites',{method:saved?'DELETE':'POST',body:JSON.stringify({profileId:profile.id,mediaId})})}catch(e){setFavorites(current=>saved?[...current,mediaId]:current.filter(id=>id!==mediaId));setError(e.message)}}
  async function reorderFavorites(fromIndex,toIndex){if(fromIndex===toIndex||fromIndex<0||toIndex<0||fromIndex>=favorites.length||toIndex>=favorites.length)return;const previous=favorites.slice(),next=favorites.slice(),[moved]=next.splice(fromIndex,1);next.splice(toIndex,0,moved);setFavorites(next);try{await request('/api/favorites/reorder',{method:'POST',body:JSON.stringify({profileId:profile.id,mediaIds:next})})}catch(e){setFavorites(previous);setError(e.message)}}
  function choosePicture(item=null){setError('');setPicturePicker({profile:item,value:item?.avatar||form.avatar||'bluey.png'})}
  async function savePicture(){try{setBusy(true);setError('');if(picturePicker.profile){const result=await request(`/api/profiles/${picturePicker.profile.id}/avatar`,{method:'POST',body:JSON.stringify({avatar:picturePicker.value}),headers:{'X-Profile-Token':''}});setProfiles(current=>current.map(item=>item.id===picturePicker.profile.id?{...item,avatar:result.avatar}:item));if(profile?.id===picturePicker.profile.id)setProfile(current=>({...current,avatar:result.avatar}))}else setForm(current=>({...current,avatar:picturePicker.value}));setPicturePicker(null)}catch(e){setError(e.message)}finally{setBusy(false)}}
  function switchProfile(){setProfile(null);setProfileToken('');setSelected(null);setMedia([]);setProgress([]);setFavorites([]);setError('');setView('select')}
  function dismissBirthday(){if(birthdayProfile)localStorage.setItem(`kingflix-birthday-${birthdayProfile.id}-${localDateInputValue()}`,'dismissed');setBirthdayProfile(null)}
  const profilePicker=<div className="profile-groups">{[false,true].map(minor=>{const group=profiles.filter(item=>(profileAge(item.dateOfBirth)??18)<18===minor);return group.length?<div className="profile-grid" key={minor?'minors':'adults'}>{group.map(item=><div className="profile-card-wrap" key={item.id}><button className="profile-card" onClick={()=>begin(item,view==='manage'?'edit':'watch')}><span className="avatar-wrap"><Avatar profile={item}/>{item.hasPin&&<span className="profile-corner" title="PIN protected"><FontAwesomeIcon icon={faLock}/></span>}<strong className="profile-age" title={`${profileAge(item.dateOfBirth)??'Unknown'} years old`}>{profileAge(item.dateOfBirth)??'—'}</strong>{view==='manage'&&<span className="edit-mark"><FontAwesomeIcon icon={faPen}/></span>}</span><span className="profile-name">{item.name}</span></button>{view==='select'&&<button className="avatar-change" type="button" onClick={()=>choosePicture(item)} aria-label={`Change ${item.name}'s profile picture`} title="Change profile picture"><FontAwesomeIcon icon={faCamera}/></button>}</div>)}</div>:null})}</div>
  const loading=profilesLoading||unlockLoading||(view==='library'&&libraryLoading)
  return <><LoadingScreen active={loading}/>{!loading&&<main className={view==='library'?'home-page':'profile-shell'}>
    {view==='select'&&<header className="site-header"><Logo/><UserButton/></header>}
    {error&&<p role="alert">{error}</p>}
    {view==='select'&&<section className="profile-stage"><h2>Who's watching?</h2>{profilePicker}<div className="manage-buttons"><button className="outline-button icon-button" onClick={()=>openManage('manage')}><FontAwesomeIcon icon={faUsersGear}/>Manage Profiles</button><button className="outline-button icon-button" onClick={()=>openManage('manage-videos')}><FontAwesomeIcon icon={faVideo}/>Manage Videos</button></div></section>}
    {view==='manage'&&<section className="profile-stage"><h2>Manage Profiles</h2>{profilePicker}<button className="profile-card add-card" onClick={()=>{resetForm();setError('');setView('create')}}><Avatar add/><span className="profile-name">Add Profile</span></button><div className="stage-actions"><button className="primary-button" onClick={()=>setView('select')}>Done</button></div></section>}
    {view==='create'&&<ProfileForm title="Add Profile" form={form} setForm={setForm} onSubmit={addProfile} onCancel={()=>{resetForm();setError('');setView('manage')}} onChooseAvatar={()=>choosePicture()} busy={busy}/>}
    {view==='edit'&&<ProfileForm title={`Edit ${profile.name}`} form={form} setForm={setForm} onSubmit={saveProfile} onCancel={()=>{setProfile(null);setProfileToken('');resetForm();setError('');setView('manage')}} onDelete={deleteProfile} onChooseAvatar={()=>choosePicture()} hasPin={profile.hasPin} busy={busy}/>}
    {view==='manage-videos'&&<ManageVideos request={request} save={updateManagedMedia} saveSeries={updateManagedSeries} onDone={()=>{setManageToken('');setView('select')}}/>}
    {picturePicker&&<PicturePicker value={picturePicker.value} setValue={value=>setPicturePicker(current=>({...current,value}))} profileName={picturePicker.profile?.name} onSave={savePicture} onCancel={()=>setPicturePicker(null)} busy={busy}/>}
    {pending&&<PinDialog profile={pending.profile} pin={pin} setPin={setPin} busy={busy} submit={value=>unlock(pending.profile,value,pending.action)} cancel={()=>{setPending(null);setPin('');setError('')}}/>}
    {birthdayProfile&&<BirthdayDialog profile={birthdayProfile} dismiss={dismissBirthday} request={request}/>} 
    {view==='library'&&<Home media={media} progress={progress} favorites={favorites} toggleFavorite={toggleFavorite} reorderFavorites={reorderFavorites} profile={profile} selected={selected} setSelected={setSelected} play={play} saveProgress={saveProgress} switchProfile={switchProfile} replayBirthday={()=>setBirthdayProfile(profile)}/>}
  </main>}</>
}

function BirthdayDialog({profile,dismiss,request}){
  const ribbonCanvas=useRef(null)
  const confettiCanvas=useRef(null)
  const[video,setVideo]=useState(null)
  const[videoError,setVideoError]=useState('')
  const[videoEnded,setVideoEnded]=useState(false)
  useEffect(()=>{let active=true;void request('/api/birthday-video').then(result=>{if(active)setVideo(result)}).catch(error=>{if(active)setVideoError(error.message)});return()=>{active=false}},[])
  useEffect(()=>{
    let active=true
    let ribbonContainer,confettiContainer,ribbonTimer,celebrationTimer
    const ribbonOptions={colors:birthdayColors,count:9,emitterSize:{width:100,height:0},scalar:1,zIndex:3,disableForReducedMotion:true}
    const startCelebration=async()=>{
      const[{ribbons},{confetti}]=await Promise.all([import('@tsparticles/ribbons'),import('@tsparticles/confetti')])
      await Promise.all([ribbons.init(),confetti.init()])
      if(!active)return
      const[shootRibbons,fire]=await Promise.all([
        ribbons.create(ribbonCanvas.current,{...ribbonOptions,count:0}),
        confetti.create(confettiCanvas.current,{count:0,colors:birthdayColors,disableForReducedMotion:true,zIndex:4}),
      ])
      ;[ribbonContainer,confettiContainer]=await Promise.all([shootRibbons({...ribbonOptions,count:0}),fire({count:0})])
      if(!active){ribbonContainer?.destroy();confettiContainer?.destroy();return}
      const releaseRibbons=()=>void shootRibbons({...ribbonOptions,count:7})
      const celebrate=()=>{
        void fire({count:5,angle:60,spread:58,startVelocity:42,position:{x:0,y:72},colors:birthdayColors,ticks:180,gravity:1,scalar:1.2})
        void fire({count:5,angle:120,spread:58,startVelocity:42,position:{x:100,y:72},colors:birthdayColors,ticks:180,gravity:1,scalar:1.2})
        void fire({count:6,angle:90,spread:100,startVelocity:5,position:{x:Math.random()*100,y:-5},colors:birthdaySnowColors,ticks:360,gravity:.45,drift:(Math.random()-.5)*1.2,scalar:1.05,flat:true})
      }
      releaseRibbons()
      celebrate()
      ribbonTimer=window.setInterval(releaseRibbons,2200)
      celebrationTimer=window.setInterval(celebrate,210)
    }
    void startCelebration().catch(error=>console.error('Unable to start birthday effects',error))
    return()=>{active=false;window.clearInterval(ribbonTimer);window.clearInterval(celebrationTimer);ribbonContainer?.destroy();confettiContainer?.destroy()}
  },[])
  return <div className="modal-backdrop birthday-backdrop"><section className={`birthday-dialog${videoEnded?' finished':''}`} role="dialog" aria-modal="true" aria-labelledby="birthday-title"><canvas ref={ribbonCanvas} className="birthday-ribbons" aria-hidden="true"/><canvas ref={confettiCanvas} className="birthday-confetti" aria-hidden="true"/><button className="birthday-close" type="button" onClick={dismiss} aria-label="Close birthday greeting"><FontAwesomeIcon icon={faXmark}/></button><h2 id="birthday-title" className="birthday-heading">Happy Birthday, <strong>{profile.name}!</strong></h2><div className="birthday-video">{video?<video autoPlay playsInline preload="metadata" onClick={event=>void event.currentTarget.play()} onEnded={()=>setVideoEnded(true)} onError={()=>setVideoError('The birthday video could not be loaded.')}><source src={video.url} type={video.mimeType}/></video>:<p>{videoError||'Loading your birthday surprise…'}</p>}</div>{videoEnded&&<div className="birthday-finale" aria-hidden="true"><h2>Happy Birthday, <strong>{profile.name}!</strong></h2></div>}</section></div>}

function Home({media,progress,favorites,toggleFavorite,reorderFavorites,profile,selected,setSelected,play,saveProgress,switchProfile,replayBirthday}){
  const[query,setQuery]=useState(''),[contentType,setContentType]=useState(''),[genre,setGenre]=useState(''),[rating,setRating]=useState(''),[sortBy,setSortBy]=useState('uploaded-desc'),[section,setSection]=useState(profile.homeVideosOnly?'home-videos':'home'),[selectedSeries,setSelectedSeries]=useState(null),[selectedSeason,setSelectedSeason]=useState(null),[infoId,setInfoId]=useState(null)
  const playerOpen=Boolean(selected)
  const[showNextCard,setShowNextCard]=useState(false)
  const player=React.useRef(null),lastCheckpoint=React.useRef(0)
  useEffect(()=>{window.history.replaceState({kingVideos:true,section:profile.homeVideosOnly?'home-videos':'home',series:null,season:null,info:null},'');const restore=event=>{if(!event.state?.kingVideos)return;setSection(event.state.section);setSelectedSeries(event.state.series||null);setSelectedSeason(event.state.season??null);setInfoId(event.state.info||null)};window.addEventListener('popstate',restore);return()=>window.removeEventListener('popstate',restore)},[])
  const positions=useMemo(()=>new Map(progress.map(item=>[item.mediaId,item.positionSeconds])),[progress])
  const featured=useMemo(()=>{
    const availableMovies=media.filter(item=>(!item.category||/^movies?$/i.test(item.category))&&!item.blocked)
    const unwatchedMovies=availableMovies.filter(item=>!positions.has(item.id))
    const choices=unwatchedMovies.length?unwatchedMovies:availableMovies
    return choices.length?choices[Math.floor(Math.random()*choices.length)]:null
  },[media,positions,profile.id])
  const filtered=media
  const searchMatches=media.filter(item=>[item.title,item.seriesTitle,...(item.genres||[])].filter(Boolean).some(value=>value.toLowerCase().includes(query.toLowerCase())))
  const categories=[...new Set(filtered.map(item=>item.category).filter(category=>category&&!/tv|series|show|short/i.test(category)))]
  const tvItems=filtered.filter(item=>/tv|series|show/i.test(item.category))
  const series=useMemo(()=>{const groups=new Map();for(const item of media.filter(item=>/tv|series|show/i.test(item.category)&&item.seriesId)){const group=groups.get(item.seriesId)||[];group.push(item);groups.set(item.seriesId,group)}return groups},[media])
  const continuing=useMemo(()=>{
    const complete=item=>item.durationSeconds>0&&(positions.get(item.id)||0)>=item.durationSeconds*.98
    const orderedSeries=new Map([...series].map(([id,episodes])=>[id,episodes.slice().sort((a,b)=>(a.seasonNumber||0)-(b.seasonNumber||0)||(a.episodeNumber||0)-(b.episodeNumber||0)||a.title.localeCompare(b.title))]))
    const cards=new Map()
    for(const item of filtered){
      if(!positions.has(item.id))continue
      let candidate=item
      if(series.has(item.seriesId)&&complete(item)){
        const episodes=orderedSeries.get(item.seriesId)
        const index=episodes.findIndex(episode=>episode.id===item.id)
        candidate=episodes.slice(index+1).find(episode=>!complete(episode))
      }
      if(candidate)cards.set(candidate.id,candidate)
    }
    return [...cards.values()]
  },[filtered,positions,series])
  const nextEpisode=useMemo(()=>{if(!selected?.seriesId)return null;const ordered=(series.get(selected.seriesId)||[]).slice().sort((a,b)=>(a.seasonNumber||0)-(b.seasonNumber||0)||(a.episodeNumber||0)-(b.episodeNumber||0)||a.title.localeCompare(b.title));const index=ordered.findIndex(item=>item.id===selected.id);return index>=0?ordered[index+1]||null:null},[selected,series])
  useEffect(()=>setShowNextCard(false),[selected?.id])
  useEffect(()=>{if(!playerOpen)return;const body=document.body,root=document.documentElement,scrollY=window.scrollY,previous={position:body.style.position,top:body.style.top,width:body.style.width,overflow:body.style.overflow,rootOverflow:root.style.overflow};body.style.position='fixed';body.style.top=`-${scrollY}px`;body.style.width='100%';body.style.overflow='hidden';root.style.overflow='hidden';return()=>{body.style.position=previous.position;body.style.top=previous.top;body.style.width=previous.width;body.style.overflow=previous.overflow;root.style.overflow=previous.rootOverflow;window.scrollTo(0,scrollY)}},[playerOpen])
  const tvCards=useMemo(()=>{const grouped=new Map(),standalone=[];for(const item of tvItems){if(!item.seriesId){standalone.push(item);continue}if(!grouped.has(item.seriesId)){const episodes=series.get(item.seriesId)||[item];grouped.set(item.seriesId,{...item,id:`series:${item.seriesId}`,title:item.seriesTitle||item.seriesId,episodeCount:episodes.length,hasCaptions:episodes.some(episode=>episode.hasCaptions),isSeries:true})}}return [...grouped.values(),...standalone]},[tvItems,series])
  const favoriteSet=new Set(favorites)
  const favoriteItems=favorites.map(id=>tvCards.find(item=>item.id===id)||filtered.find(item=>item.id===id)).filter(Boolean)
  const homeRows=[{title:'Continue Watching',items:continuing},{title:'My List',items:favoriteItems},...categories.filter(category=>!/movie|home[- ]?videos?/i.test(category)).slice(0,2).map(category=>({title:category,items:/tv|series|show/i.test(category)?tvCards:filtered.filter(item=>item.category===category)}))]
  const releaseOrder=item=>{const match=String(item.releaseDate||'').match(/^(\d{4})(?:-(\d{2}))?(?:-(\d{2}))?/);return match?Number(match[1])*10000+Number(match[2]||0)*100+Number(match[3]||0):(item.year||0)*10000}
  const newestFirst=(a,b)=>releaseOrder(b)-releaseOrder(a)||a.title.localeCompare(b.title)
  const latestAdded=(a,b)=>String(b.createdAt||'').localeCompare(String(a.createdAt||''))||a.title.localeCompare(b.title)
  const movies=filtered.filter(item=>!item.category||/movie/i.test(item.category))
  const shorts=filtered.filter(item=>/short/i.test(item.category))
  const homeVideos=filtered.filter(item=>/home[- ]?videos?/i.test(item.category||'')).sort(newestFirst)
  const matchingSeries=new Set(searchMatches.map(item=>item.seriesId).filter(Boolean))
  const unfilteredSearchItems=[...tvCards.filter(item=>item.isSeries?matchingSeries.has(item.seriesId):searchMatches.some(match=>match.id===item.id)),...searchMatches.filter(item=>!/tv|series|show/i.test(item.category))]
  const availableGenres=[...new Set(media.flatMap(item=>item.genres||[]))].sort((a,b)=>a.localeCompare(b))
  const searchSorters={'uploaded-desc':latestAdded,'release-desc':newestFirst,'release-asc':(a,b)=>{const aDate=releaseOrder(a),bDate=releaseOrder(b);return !aDate&&!bDate?a.title.localeCompare(b.title):!aDate?1:!bDate?-1:aDate-bDate||a.title.localeCompare(b.title)},'title-asc':(a,b)=>a.title.localeCompare(b.title),'title-desc':(a,b)=>b.title.localeCompare(a.title)}
  const ratingOrder=['G','PG','PG-13','R','NC-17','TV-Y','TV-Y7','TV-G','TV-PG','TV-14','TV-MA','NR']
  const availableRatings=[...new Set(media.map(item=>item.rating).filter(Boolean))].sort((a,b)=>{const ai=ratingOrder.indexOf(a),bi=ratingOrder.indexOf(b);return (ai<0?99:ai)-(bi<0?99:bi)||a.localeCompare(b)})
  const searchItems=unfilteredSearchItems.filter(item=>{const category=item.category||'',homeVideo=/home[- ]?videos?/i.test(category);if(contentType==='shorts'&&!/short/i.test(category))return false;if(contentType==='home-videos'&&!homeVideo)return false;if(contentType==='tv'&&!item.isSeries&&!/tv|series|show/i.test(category))return false;if(contentType==='movies'&&(item.isSeries||homeVideo||/tv|series|show|short/i.test(category)))return false;if(rating&&(item.isSeries?!(series.get(item.seriesId)||[]).some(episode=>episode.rating===rating):item.rating!==rating))return false;return !genre||(item.isSeries?(series.get(item.seriesId)||[]).some(episode=>(episode.genres||[]).includes(genre)):(item.genres||[]).includes(genre))}).sort(searchSorters[sortBy])
  const searchRows=[{title:query?`Results for "${query}"`:'All Titles',items:searchItems}]
  const links=profile.homeVideosOnly?[['home-videos','Home Videos']]:[['home-videos','Home Videos'],['movies','Movies'],['tv','TV'],['collections','Series']]
  function navigate(path,seriesId=null,season=null,info=null){if(profile.homeVideosOnly&&['home','movies','tv','shorts','collections'].includes(path))path='home-videos';window.history.pushState({kingVideos:true,section:path,series:seriesId,season,info},'');setSelectedSeries(seriesId);setSelectedSeason(season);setInfoId(info);setSection(path)}
  function openMedia(item){navigate('info',null,null,item.id)}
  function openInfo(item){navigate('info',null,null,item.isSeries?item.id:item.id)}
  function checkpoint(){const second=Math.floor(player.current?.currentTime||0);if(second-lastCheckpoint.current>=15){lastCheckpoint.current=second;saveProgress(second)}}
  function savePlayerProgress(){if(player.current)saveProgress(player.current.currentTime)}
  function togglePlayerControls(event){if(event.target.closest?.('.vds-controls,button,input,select,[role="menu"]'))return;player.current?.remoteControl?.toggleControls(event.nativeEvent)}
  async function togglePlayback(event){const button=event?.currentTarget;if(button){window.clearTimeout(button._playFeedbackTimer);button.classList.remove('play-feedback');void button.offsetWidth;button.classList.add('play-feedback');button._playFeedbackTimer=window.setTimeout(()=>button.classList.remove('play-feedback'),550)}try{if(player.current?.paused)await player.current.play();else await player.current?.pause()}catch{}}
  function skipPlayer(seconds,event){if(!player.current)return;const button=event?.currentTarget;if(button){window.clearTimeout(button._skipFeedbackTimer);button._skipFeedbackTotal=(button._skipFeedbackTotal||0)+seconds;button.dataset.feedback=`${button._skipFeedbackTotal>0?'+':''}${button._skipFeedbackTotal}`;button.classList.remove('skip-feedback');void button.offsetWidth;button.classList.add('skip-feedback');button._skipFeedbackTimer=window.setTimeout(()=>{button.classList.remove('skip-feedback');button._skipFeedbackTotal=0;button.dataset.feedback=seconds>0?'+10':'−10'},700)}player.current.remoteControl?.pauseControls(event?.nativeEvent);player.current.remoteControl?.resumeControls(event?.nativeEvent);const duration=Number.isFinite(player.current.duration)?player.current.duration:Infinity;player.current.currentTime=Math.max(0,Math.min(duration,player.current.currentTime+seconds));savePlayerProgress()}
  async function exitPlayerFullscreen(){
    const video=player.current?.querySelector?.('video')
    const nativeFullscreen=Boolean(video?.webkitDisplayingFullscreen||video?.webkitPresentationMode==='fullscreen')
    const nativeExit=nativeFullscreen?new Promise(resolve=>{let finished=false;const done=()=>{if(finished)return;finished=true;video?.removeEventListener?.('webkitendfullscreen',done);resolve()};video?.addEventListener?.('webkitendfullscreen',done,{once:true});window.setTimeout(done,1200)}):Promise.resolve()
    try{
      if(typeof player.current?.exitFullscreen==='function')await player.current.exitFullscreen('prefer-media')
    }catch{}
    try{
      if(video?.webkitDisplayingFullscreen&&typeof video.webkitExitFullscreen==='function')video.webkitExitFullscreen()
      else if(video?.webkitPresentationMode==='fullscreen'&&typeof video.webkitSetPresentationMode==='function')video.webkitSetPresentationMode('inline')
    }catch{}
    try{
      if(document.fullscreenElement&&typeof document.exitFullscreen==='function')await document.exitFullscreen()
      else if(document.webkitFullscreenElement&&typeof document.webkitExitFullscreen==='function')await document.webkitExitFullscreen()
    }catch{}
    await nativeExit
  }
  async function finishPlayback(){savePlayerProgress();await exitPlayerFullscreen();setShowNextCard(Boolean(nextEpisode))}
  async function closePlayer(){savePlayerProgress();await exitPlayerFullscreen();setSelected(null)}
  const episodes=(series.get(selectedSeries)||[]).slice().sort((a,b)=>(a.seasonNumber||0)-(b.seasonNumber||0)||(a.episodeNumber||0)-(b.episodeNumber||0)||a.title.localeCompare(b.title))
  const infoItem=tvCards.find(item=>item.id===infoId)||media.find(item=>item.id===infoId)
  const infoIsSeries=Boolean(infoItem&&(infoItem.isSeries||String(infoItem.id).startsWith('series:')))
  const infoEpisodes=infoItem?.seriesId?(series.get(infoItem.seriesId)||[]).slice().sort((a,b)=>(a.seasonNumber||0)-(b.seasonNumber||0)||(a.episodeNumber||0)-(b.episodeNumber||0)||a.title.localeCompare(b.title)):[]
  const watchedInfoEpisode=infoEpisodes.length?progress.map(entry=>infoEpisodes.find(item=>item.id===entry.mediaId)).find(Boolean):null
  const infoPlayable=infoIsSeries?(watchedInfoEpisode||infoEpisodes[0]):infoItem
  const infoPosition=infoPlayable?positions.get(infoPlayable.id)||0:0
  const nextInfoStart=infoEpisodes.findIndex(item=>item.id===infoPlayable?.id)+1
  const nextInfoEpisodes=infoEpisodes.length?infoEpisodes.slice(Math.max(0,nextInfoStart),Math.max(0,nextInfoStart)+12):[]
  const similarTitles=infoItem&&!infoItem.seriesId&&!infoItem.isSeries?media.filter(item=>item.id!==infoItem.id&&(infoItem.category==='short'?item.category==='short':/movie/i.test(item.category||'movie'))).map(item=>({...item,matchCount:(item.genres||[]).filter(genre=>(infoItem.genres||[]).includes(genre)).length})).filter(item=>item.matchCount>0).sort((a,b)=>b.matchCount-a.matchCount||(b.year||0)-(a.year||0)).slice(0,12):[]
  const infoRelatedRows=infoIsSeries?[...new Set(infoEpisodes.map(item=>item.seasonNumber??1))].sort((a,b)=>a-b).map(season=>({title:season===0?'Shorts':`Season ${season}`,items:infoEpisodes.filter(item=>(item.seasonNumber??1)===season)})):[{title:infoItem?.seriesId?'Next Episodes':infoItem?.category==='short'?'Similar Shorts':'Similar Movies',items:infoItem?.seriesId?nextInfoEpisodes:similarTitles}]
  return <><header className="home-header"><button className="home-logo" type="button" onClick={()=>navigate('home')} aria-label="Kingflix home"><Logo/></button><nav>{links.map(([path,label])=><button key={path} className={section===path?'active':''} onClick={()=>navigate(path)}>{label}</button>)}<button className={section==='search'?'active':''} onClick={()=>navigate('search')}><FontAwesomeIcon icon={faMagnifyingGlass}/> Search</button></nav><div className="profile-actions">{birthdayAvailable(profile.dateOfBirth)&&<button className="birthday-replay" type="button" onClick={replayBirthday} aria-label={`Replay ${profile.name}'s birthday celebration`} title="Replay birthday celebration"><FontAwesomeIcon icon={faGift}/></button>}<button className="active-profile" onClick={switchProfile} aria-label={`Switch from ${profile.name}`}><Avatar profile={profile}/></button></div></header>
    {section==='home'&&<><Hero featured={featured} play={play} info={openInfo}/><Shelves rows={homeRows} media={media} positions={positions} favorites={favoriteSet} toggleFavorite={toggleFavorite} reorderFavorites={reorderFavorites} onEmptyMyList={()=>navigate('search')} play={openMedia} resume={item=>play(item,positions.get(item.id)||0)}/></>}
    {section==='movies'&&<BrowsePage key="Movies" title="Movies" items={movies} sorters={searchSorters} positions={positions} favorites={favoriteSet} toggleFavorite={toggleFavorite} play={openMedia}/>}
    {section==='tv'&&<BrowsePage key="TV" title="TV" items={tvCards} sorters={searchSorters} positions={positions} favorites={favoriteSet} toggleFavorite={toggleFavorite} play={openMedia}/>}
    {section==='collections'&&<CollectionsPage selectedCollection={selectedSeries} tvCards={tvCards} media={media} positions={positions} favorites={favoriteSet} toggleFavorite={toggleFavorite} play={openMedia} openCollection={id=>navigate('collections',id)} onBack={()=>navigate('collections')}/>}
    {section==='home-videos'&&<HomeVideosTimeline items={homeVideos} positions={positions} favorites={favoriteSet} toggleFavorite={toggleFavorite} play={openMedia}/>}
    {section==='shorts'&&<BrowsePage key="Shorts" title="Shorts" items={shorts} sorters={searchSorters} positions={positions} favorites={favoriteSet} toggleFavorite={toggleFavorite} play={openMedia}/>}
    {section==='series'&&<SeriesPage series={episodes} selectedSeason={selectedSeason} positions={positions} play={openMedia} onBack={()=>window.history.back()} onSelectSeason={season=>navigate('series',selectedSeries,season)}/>}
    {section==='info'&&infoItem&&<DetailsPage item={infoItem} playable={infoPlayable} position={infoPosition} relatedRows={infoRelatedRows} positions={positions} favorites={favoriteSet} saved={favoriteSet.has(infoItem.id)} play={play} openDetails={openMedia} openSeries={()=>navigate('series',infoItem.seriesId)} toggleFavorite={toggleFavorite} onBack={()=>window.history.back()}/>}
    {section==='search'&&<><section className="search-page"><div className="home-search"><FontAwesomeIcon icon={faMagnifyingGlass}/><input autoFocus aria-label="Search videos" placeholder="Search titles" value={query} onChange={event=>setQuery(event.target.value)}/></div><div className="search-filters"><label>Type<select value={contentType} onChange={event=>setContentType(event.target.value)}><option value="">All titles</option>{!profile.homeVideosOnly&&<><option value="movies">Movies</option><option value="tv">TV</option><option value="shorts">Shorts</option></>}<option value="home-videos">Home Videos</option></select></label><label>Genre<select value={genre} onChange={event=>setGenre(event.target.value)}><option value="">All genres</option>{availableGenres.map(item=><option key={item} value={item}>{item}</option>)}</select></label><label>Rating<select value={rating} onChange={event=>setRating(event.target.value)}><option value="">All ratings</option>{availableRatings.map(item=><option key={item} value={item}>{item}</option>)}</select></label><SortControl value={sortBy} onChange={setSortBy}/></div></section><SearchGrid title={searchRows[0].title} query={`${query}|${contentType}|${genre}|${rating}|${sortBy}`} items={searchItems} positions={positions} favorites={favoriteSet} toggleFavorite={toggleFavorite} play={openMedia}/></>}
    {selected&&<section className="player-overlay"><div className="player-stage"><MediaPlayer key={selected.id} ref={player} title={selected.title} src={{src:selected.url,type:selected.mimeType||'video/mp4'}} autoPlay playsInline load="eager" crossOrigin={mediaCrossOrigin(selected.url)} onClick={togglePlayerControls} onLoadedMetadata={()=>{if(player.current)player.current.currentTime=selected.startAt||0;lastCheckpoint.current=Math.floor(selected.startAt||0)}} onTimeUpdate={checkpoint} onPlay={()=>setShowNextCard(false)} onPause={savePlayerProgress} onEnded={finishPlayback} onSeeked={savePlayerProgress}><MediaProvider>{selected.subtitleUrl&&<Track default src={selected.subtitleUrl} kind="subtitles" label="English" lang="en" type="vtt"/>}</MediaProvider><DefaultVideoLayout icons={defaultLayoutIcons} noGestures slots={{playButton:null}}/><div className="player-pause-info"><Logo/><strong>{selected.title}</strong><span>{[selected.year,selected.rating,formatDuration(selected.durationSeconds)].filter(Boolean).join(' · ')}</span></div><button className="player-close" onClick={closePlayer} aria-label="Close video" title="Close video"><FontAwesomeIcon icon={faXmark}/></button><div className="player-center-controls"><button className="player-skip" data-feedback="−10" onClick={event=>skipPlayer(-10,event)} aria-label="Go back 10 seconds"><FontAwesomeIcon icon={faRotateLeft}/><b>10</b></button><button className="player-center-play" onClick={togglePlayback} aria-label="Play or pause video"><FontAwesomeIcon className="center-play-icon" icon={faPlay}/><FontAwesomeIcon className="center-pause-icon" icon={faPause}/></button><button className="player-skip" data-feedback="+10" onClick={event=>skipPlayer(10,event)} aria-label="Go forward 10 seconds"><FontAwesomeIcon icon={faRotateRight}/><b>10</b></button></div>{showNextCard&&nextEpisode&&<button className="next-episode-card" onClick={()=>play(nextEpisode)} aria-label={`Play next episode: ${nextEpisode.title}`}><span className="next-episode-label">Up next</span>{nextEpisode.thumbnailUrl?<img src={nextEpisode.thumbnailUrl} alt=""/>:<span className="next-episode-placeholder"><FontAwesomeIcon icon={faPlay}/></span>}<span className="next-episode-copy"><small>{nextEpisode.seasonNumber?`Season ${nextEpisode.seasonNumber} · `:''}Episode {nextEpisode.episodeNumber||''}</small><strong>{nextEpisode.title}</strong><span><FontAwesomeIcon icon={faPlay}/> Play next episode</span></span></button>}</MediaPlayer></div></section>}
  </>
}

function Hero({featured,play,info}){return featured&&<section className="hero" style={featured.thumbnailUrl?{'--hero-image':`url("${featured.thumbnailUrl}")`}:undefined}><div className="hero-content"><small>Featured Presentation</small><h1>{featured.title}</h1><p>{featured.description||'Watch on King Videos.'}</p><div><button className="hero-play icon-button" onClick={()=>play(featured,0)}><FontAwesomeIcon icon={faPlay}/>Play</button><button className="hero-info icon-button" onClick={()=>info(featured)}><FontAwesomeIcon icon={faCircleInfo}/>Info</button></div></div></section>}
function DetailsPage({item,playable,position,relatedRows,positions,favorites,saved,play,openDetails,openSeries,toggleFavorite,onBack}){const isSeriesDetail=item.isSeries||String(item.id).startsWith('series:'),hasProgress=position>0,title=isSeriesDetail?(item.seriesTitle||item.title):item.title,blocked=Boolean(playable?.blocked);return <section className="details-page"><div className="info-page" style={item.thumbnailUrl?{'--info-image':`url("${item.thumbnailUrl}")`}:undefined}><button className="series-back icon-button" onClick={onBack}><FontAwesomeIcon icon={faArrowLeft}/>Back</button><div className="info-content"><small>{isSeriesDetail?'TV Show':item.category||'Movie'}</small><h1>{title}</h1><div className="title-meta">{item.year&&<span>{item.year}</span>}{item.rating&&<span>{item.rating}</span>}{isSeriesDetail&&<span>{item.episodeCount} episodes</span>}{!isSeriesDetail&&item.durationSeconds&&<span>{formatDuration(item.durationSeconds)}</span>}{blocked&&<span className="blocked-label"><FontAwesomeIcon icon={faLock}/> Blocked</span>}</div><p>{item.description||'Watch on King Videos.'}</p>{blocked&&<p className="blocked-note">Blocked — this title is waiting to be watched together before playback is enabled.</p>}{item.genres?.length>0&&<div className="genre-list">{item.genres.map(genre=><span key={genre}>{genre}</span>)}</div>}<div className="info-actions">{!isSeriesDetail&&playable&&<button className="hero-play icon-button" disabled={blocked} onClick={()=>play(playable,position)}><FontAwesomeIcon icon={blocked?faLock:faPlay}/>{blocked?'Blocked':hasProgress?'Continue':'Watch'}</button>}{!isSeriesDetail&&playable&&hasProgress&&!blocked&&<button className="hero-info icon-button" onClick={()=>play(playable,0)}><FontAwesomeIcon icon={faPlay}/>Restart</button>}{item.seriesId&&<button className="hero-info icon-button" onClick={openSeries}><FontAwesomeIcon icon={faCircleInfo}/>View Seasons</button>}{canAddToList(item)&&<button className="hero-info icon-button" onClick={()=>toggleFavorite(item.id)}><FontAwesomeIcon icon={saved?faCheck:faPlus}/>{saved?'In My List':'Add to My List'}</button>}</div></div></div>{relatedRows.some(row=>row.items.length>0)&&<div className="details-related">{relatedRows.filter(row=>row.items.length>0).map(row=><MediaRow key={row.title} title={row.title} items={row.items} positions={positions} favorites={favorites} toggleFavorite={toggleFavorite} play={openDetails}/>)}</div>}</section>}
function Shelves({rows,media,positions,favorites,toggleFavorite,reorderFavorites,onEmptyMyList,play,resume}){const visible=rows.filter(row=>row.items.length||row.title==='My List'||row.title==='Continue Watching');return <div className="shelves">{visible.map(row=><MediaRow key={row.title} title={row.title} items={row.items} positions={positions} favorites={favorites} toggleFavorite={toggleFavorite} reorderFavorites={reorderFavorites} onEmptyMyList={onEmptyMyList} play={row.title==='Continue Watching'&&resume?resume:play}/>)}{!media.length&&<p className="empty-library">No videos yet. Add a video to the catalog to begin.</p>}</div>}
function CollectionsPage({selectedCollection,tvCards,media,positions,favorites,toggleFavorite,play,openCollection,onBack}){
  const collection=collections.find(item=>item.id===selectedCollection)
  if(collection){
    const items=[...tvCards.filter(item=>collection.showIds.includes(item.seriesId)),...media.filter(item=>collection.mediaIds.includes(item.id))].sort((a,b)=>a.title.localeCompare(b.title))
    return <><section className="browse-heading"><button type="button" className="series-back icon-button" onClick={onBack}><FontAwesomeIcon icon={faArrowLeft}/>Series</button><h1>{collection.title}</h1></section><SearchGrid query={collection.id} items={items} positions={positions} favorites={favorites} toggleFavorite={toggleFavorite} play={play} emptyMessage="No titles in this collection are available for this profile yet."/></>
  }
  return <section className="collections-page"><header className="browse-heading"><h1>Series</h1></header><div className="search-results"><div className="search-grid">{collections.map(item=><article className="shelf-card search-card" key={item.id}><button type="button" className="card-main" onClick={()=>openCollection(item.id)}><span className="card-art"><img loading="lazy" decoding="async" src={import.meta.env.BASE_URL+item.thumbnail} alt=""/><strong>{item.title}</strong></span><span className="card-synopsis">{item.description}</span></button></article>)}</div></div></section>
}

function SortControl({value,onChange}){return <label className="sort-control">Sort by<select value={value} onChange={event=>onChange(event.target.value)}><option value="uploaded-desc">Recently uploaded</option><option value="release-desc">Release date: newest</option><option value="release-asc">Release date: oldest</option><option value="title-asc">Title: A–Z</option><option value="title-desc">Title: Z–A</option></select></label>}
function BrowsePage({title,items,sorters,positions,favorites,toggleFavorite,play}){
  const[sortBy,setSortBy]=useState('uploaded-desc')
  const latestItems=items.slice().sort(sorters['uploaded-desc']).slice(0,10)
  const browseItems=items.slice().sort(sorters[sortBy])
  return <><section className="browse-heading"><h1>{title}</h1></section><Shelves rows={[{title:'Latest Added',items:latestItems}]} media={items} positions={positions} favorites={favorites} toggleFavorite={toggleFavorite} play={play}/><SearchGrid title="Browse" headerAction={<SortControl value={sortBy} onChange={setSortBy}/>} query={title+'|'+sortBy} items={browseItems} positions={positions} favorites={favorites} toggleFavorite={toggleFavorite} play={play}/></>
}

function HomeVideosTimeline({items,positions,favorites,toggleFavorite,play}){
  const[visibleGroupCount,setVisibleGroupCount]=useState(12)
  const loadMoreRef=useRef(null)
  const timeline=useMemo(()=>{const years=new Map();for(const item of items){const match=String(item.releaseDate||item.year||'').match(/^(\d{4})(?:-(\d{2}))?(?:-(\d{2}))?/),year=match?.[1]||'Undated',month=match?.[2]||'',day=match?.[3]||'',dateKey=year==='Undated'?'undated':`${year}-${month||'00'}-${day||'00'}`;if(!years.has(year))years.set(year,new Map());const dates=years.get(year);if(!dates.has(dateKey))dates.set(dateKey,{year,month,day,items:[]});dates.get(dateKey).items.push(item)}return[...years.entries()].sort(([a],[b])=>a==='Undated'?1:b==='Undated'?-1:Number(b)-Number(a)).map(([year,dates])=>({year,dates:[...dates.values()].sort((a,b)=>`${b.year}-${b.month}-${b.day}`.localeCompare(`${a.year}-${a.month}-${a.day}`))}))},[items])
  const totalGroups=useMemo(()=>timeline.reduce((total,year)=>total+year.dates.length,0),[timeline])
  const allGroups=useMemo(()=>timeline.flatMap(year=>year.dates.map(group=>({...group,index:0}))).map((group,index)=>({...group,index})),[timeline])
  const visibleTimeline=useMemo(()=>{let remaining=visibleGroupCount;return timeline.map(year=>{const dates=year.dates.slice(0,Math.max(0,remaining));remaining-=dates.length;return{...year,dates}}).filter(year=>year.dates.length)},[timeline,visibleGroupCount])
  useEffect(()=>{const target=loadMoreRef.current;if(!target||visibleGroupCount>=totalGroups)return;const observer=new IntersectionObserver(entries=>{if(entries[0]?.isIntersecting)setVisibleGroupCount(count=>Math.min(count+12,totalGroups))},{rootMargin:'800px 0px'});observer.observe(target);return()=>observer.disconnect()},[visibleGroupCount,totalGroups])
  function dateLabels(group){if(group.year==='Undated')return{primary:'DATE',secondary:'Unknown',weekday:''};if(!group.month)return{primary:'YEAR',secondary:group.year,weekday:''};const date=new Date(`${group.year}-${group.month}-${group.day||'01'}T12:00:00Z`),month=date.toLocaleString('en-US',{month:'short',timeZone:'UTC'}).toUpperCase();return group.day?{primary:month,secondary:group.day,weekday:date.toLocaleString('en-US',{weekday:'short',timeZone:'UTC'})}:{primary:month,secondary:group.year,weekday:''}}
  function jumpTo(group){setVisibleGroupCount(count=>Math.max(count,group.index+1));requestAnimationFrame(()=>requestAnimationFrame(()=>document.getElementById(`date-${group.year}-${group.month}-${group.day}`)?.scrollIntoView({behavior:'smooth',block:'start'})))}
  return <main className="home-videos-page"><header><h1>Home Videos</h1><p>Browse family memories by recording date.</p></header>{timeline.length?<><div className="home-timeline-shell"><nav className="timeline-index" aria-label="Home video dates">{timeline.map(year=><div className="timeline-index-year" key={year.year}><button type="button" onClick={()=>jumpTo(allGroups.find(group=>group.year===year.year))}>{year.year}</button>{year.dates.map(group=>{const labels=dateLabels(group);return <button className="timeline-index-date" type="button" key={`${group.year}-${group.month}-${group.day}`} onClick={()=>jumpTo(allGroups.find(item=>item.year===group.year&&item.month===group.month&&item.day===group.day))}><i/><span>{labels.primary} {labels.secondary}</span></button>})}</div>)}</nav><div className="home-timeline">{visibleTimeline.map(year=><section className="timeline-year" key={year.year}><h2 className="timeline-year-heading">{year.year}</h2><div className="timeline-year-entries">{year.dates.map(group=>{const key=`date-${group.year}-${group.month}-${group.day}`,labels=dateLabels(group),groupTitle=group.items.length===1?group.items[0].title:(group.items[0].seriesTitle&&group.items[0].seriesTitle!=='Home Videos'?group.items[0].seriesTitle:`${group.items.length} Home Videos`);return <article className="timeline-entry" id={key} key={key}><div className="timeline-date"><span>{labels.primary} {labels.secondary}</span>{labels.weekday&&<small>{labels.weekday}</small>}</div><span className="timeline-dot" aria-hidden="true"/><div className="timeline-content"><div className="timeline-group-heading"><strong>{groupTitle}</strong><span>{group.items.length} video{group.items.length===1?'':'s'}</span></div><div className="timeline-video-grid">{group.items.map(item=><MediaCard key={item.id} item={item} position={positions.get(item.id)} favorite={favorites.has(item.id)} toggleFavorite={toggleFavorite} play={play}/>)}</div></div></article>})}</div></section>)}</div></div>{visibleGroupCount<totalGroups&&<div ref={loadMoreRef} className="timeline-load-more" aria-label="Loading more home videos"><span/></div>}</>:<p className="empty-search">Home Videos will appear here as they finish uploading.</p>}</main>
}

function formatDuration(seconds){if(!seconds)return '';const minutes=Math.round(seconds/60),hours=Math.floor(minutes/60),remaining=minutes%60;return hours?`${hours}h${remaining?` ${remaining}m`:''}`:`${minutes}m`}
function canAddToList(item){return Boolean(item&&(item.isSeries||String(item.id).startsWith('series:')||(!item.seriesId&&/movie/i.test(item.category||'movie'))))}
function MediaCard({item,position,favorite,toggleFavorite,play,search=false,reorder,dragging=false,cardRef,dragProps}){const details=[item.year,item.isSeries?`${item.episodeCount} episodes`:formatDuration(item.durationSeconds)].filter(Boolean),synopsis=item.description||'Watch on King Videos.',watched=position===undefined?null:item.durationSeconds?Math.min(100,Math.max(0,position/item.durationSeconds*100)):Math.min(92,Math.max(8,position/60));return <article ref={cardRef} id={`media-${item.id}`} className={`shelf-card${search?' search-card':''}${reorder?' reorderable':''}${dragging?' dragging':''}${item.blocked?' blocked':''}`} {...dragProps}><button className="card-main" onClick={()=>play(item)}><span className="card-art">{item.thumbnailUrl?<img loading="lazy" decoding="async" src={item.thumbnailUrl} alt=""/>:<span className="poster-placeholder"><FontAwesomeIcon icon={faPlay}/></span>}{item.blocked&&<span className="card-blocked"><FontAwesomeIcon icon={faLock}/> Blocked</span>}{watched!==null&&<span className="watch-progress" style={{'--watched':`${watched}%`}}/>}<strong title={item.title}>{item.title}</strong></span><span className="card-details"><span className="card-details-text">{details.join(' \u2022 ')||item.category||'Video'}</span>{item.rating&&<span className="card-rating" aria-label={`Rated ${item.rating}`}>{item.rating}</span>}{item.hasCaptions&&<span className="card-captions" role="img" aria-label="Closed captions available" title="Closed captions available"><FontAwesomeIcon icon={faClosedCaptioning}/></span>}</span><span className="card-synopsis" title={synopsis}>{synopsis}</span></button>{canAddToList(item)&&<button className={`favorite-button${favorite?' saved':''}`} onClick={()=>toggleFavorite(item.id)} aria-label={`${favorite?'Remove from':'Add to'} My List`} title={`${favorite?'Remove from':'Add to'} My List`}><FontAwesomeIcon icon={favorite?faCheck:faPlus}/></button>}{reorder&&<div className="reorder-controls"><button type="button" onClick={()=>reorder.move(-1)} disabled={reorder.index===0} aria-label={`Move ${item.title} left`}><FontAwesomeIcon icon={faChevronLeft}/></button><span title="Drag to reorder"><FontAwesomeIcon icon={faGripVertical}/></span><button type="button" onClick={()=>reorder.move(1)} disabled={reorder.index===reorder.total-1} aria-label={`Move ${item.title} right`}><FontAwesomeIcon icon={faChevronRight}/></button></div>}</article>}

function SearchGrid({title,headerAction,query,items,positions,favorites,toggleFavorite,play,emptyMessage='No titles match your search.'}){const[visibleCount,setVisibleCount]=useState(24),sentinel=React.useRef(null);useEffect(()=>setVisibleCount(24),[query]);useEffect(()=>{const node=sentinel.current;if(!node||visibleCount>=items.length)return;const observer=new IntersectionObserver(entries=>{if(entries[0].isIntersecting)setVisibleCount(count=>Math.min(count+24,items.length))},{rootMargin:'500px'});observer.observe(node);return()=>observer.disconnect()},[visibleCount,items.length]);const visible=items.slice(0,visibleCount);return <section className="search-results">{(title||headerAction)&&<div className={headerAction?"grid-heading browse-grid-heading":"grid-heading"}><h2>{title}</h2>{headerAction}</div>}{visible.length?<div className="search-grid">{visible.map(item=><MediaCard key={item.id} item={item} position={positions.get(item.id)} favorite={favorites.has(item.id)} toggleFavorite={toggleFavorite} play={play} search/>)}</div>:<p className="empty-search">{emptyMessage}</p>}<div className="search-sentinel" ref={sentinel}>{visibleCount<items.length?'Loading more…':''}</div></section>}

function GenreFilters({selected,setSelected}){return <div className="genre-filters" aria-label="Filter by genre"><button className={!selected?'active':''} onClick={()=>setSelected('')}>All</button>{genres.map(item=><button className={selected===item?'active':''} key={item} onClick={()=>setSelected(item)}>{item}</button>)}</div>}

function SeriesPage({series,selectedSeason,positions,play,onBack,onSelectSeason}){const show=series[0];if(!show)return null;const seasonName=season=>season===0?'Shorts':`Season ${season}`,seasons=[...new Set(series.map(item=>item.seasonNumber??1))].sort((a,b)=>a-b),episodes=selectedSeason===null?[]:series.filter(item=>(item.seasonNumber??1)===selectedSeason),credit=seriesCredits[show.seriesId];return <section className="series-page"><button className="series-back icon-button" onClick={onBack}><FontAwesomeIcon icon={faArrowLeft}/>{selectedSeason===null?'Back to TV':`Back to ${show.seriesTitle||show.seriesId}`}</button>{selectedSeason===null?<><header className="series-intro">{show.thumbnailUrl&&<img src={show.thumbnailUrl} alt=""/>}<div><small>TV Series</small><h1>{show.seriesTitle||show.seriesId}</h1><p>{show.description}</p><span>{seasons.length} season{seasons.length===1?'':'s'} • {series.length} episodes{show.rating?` • ${show.rating}`:''}</span></div></header><h2>Seasons</h2><div className="season-grid">{seasons.map(season=>{const count=series.filter(item=>(item.seasonNumber??1)===season).length;return <button className="season-card" key={season} onClick={()=>onSelectSeason(season)}>{show.thumbnailUrl?<img src={show.thumbnailUrl} alt=""/>:<span className="poster-placeholder"><FontAwesomeIcon icon={faPlay}/></span>}<span><strong>{seasonName(season)}</strong><small>{count} episode{count===1?'':'s'}</small></span></button>})}</div></>:<><header className="season-heading"><small>{show.seriesTitle||show.seriesId}</small><h1>{seasonName(selectedSeason)}</h1><span>{episodes.length} episode{episodes.length===1?'':'s'}</span></header><div className="episode-grid">{episodes.map(item=><button className="episode-card" key={item.id} onClick={()=>play(item)}>{item.thumbnailUrl?<img src={item.thumbnailUrl} alt=""/>:<span className="poster-placeholder"><FontAwesomeIcon icon={faPlay}/></span>}{positions.has(item.id)&&<span className="watch-progress" style={{'--watched':`${Math.min(92,Math.max(8,positions.get(item.id)/60))}%`}}/>}<span className="episode-copy"><small>{selectedSeason===0?'Short':`Episode ${item.episodeNumber||''}`}</small><strong>{item.title}</strong><span>{item.description}</span></span></button>)}</div></>}{credit&&<p className="metadata-credit">Episode descriptions from <a href={credit.url} target="_blank" rel="noreferrer">{credit.label}</a>, available under CC BY-SA.</p>}</section>}

function MediaRow({title,items,positions,favorites,toggleFavorite,reorderFavorites,onEmptyMyList,play}){
  const track=React.useRef(null),snapTimer=React.useRef(null),cardRefs=React.useRef(new Map()),dragOrigin=React.useRef(null),dragGhost=React.useRef(null),dragOffset=React.useRef({x:0,y:0})
  const[edges,setEdges]=useState({start:true,end:true}),[draggedId,setDraggedId]=useState(null),[previewItems,setPreviewItems]=useState(items),isMyList=title==='My List'
  useEffect(()=>{if(!draggedId)setPreviewItems(items)},[items,draggedId])
  useEffect(()=>{
    const node=track.current
    if(!node)return
    const measure=()=>{
      const first=node.firstElementChild,last=node.lastElementChild,viewport=node.getBoundingClientRect(),firstBox=first?.getBoundingClientRect(),lastBox=last?.getBoundingClientRect()
      return{start:!firstBox||firstBox.right>viewport.left+2,end:!lastBox||lastBox.left<viewport.right-2,max:Math.max(0,node.scrollWidth-node.clientWidth)}
    }
    const update=()=>{const{start,end}=measure();setEdges({start,end})}
    const settle=()=>{
      if(title==='Latest Added')return
      clearTimeout(snapTimer.current)
      snapTimer.current=setTimeout(()=>{
        const{start,end,max}=measure()
        if(max<=1)return
        // A short shelf can show both ends. Always settle toward the nearest one.
        const target=start&&end?(node.scrollLeft<=max/2?0:max):start?0:end?max:null
        if(target!==null&&Math.abs(target-node.scrollLeft)>1)node.scrollTo({left:target,behavior:'smooth'})
      },140)
    }
    const onScroll=()=>{update();settle()}
    update()
    node.addEventListener('scroll',onScroll,{passive:true})
    window.addEventListener('resize',update)
    return()=>{clearTimeout(snapTimer.current);node.removeEventListener('scroll',onScroll);window.removeEventListener('resize',update)}
  },[items.length,title])
  const cardPositions=()=>new Map([...cardRefs.current].map(([id,node])=>[id,node?.getBoundingClientRect()]))
  function animateCards(before,duration,skipId=null){requestAnimationFrame(()=>requestAnimationFrame(()=>{for(const[id,node]of cardRefs.current){if(!node||id===skipId)continue;const old=before.get(id),now=node.getBoundingClientRect(),x=(old?.left||now.left)-now.left;if(Math.abs(x)>1)node.animate([{transform:`translateX(${x}px)`},{transform:'translateX(0)'}],{duration,easing:'cubic-bezier(.22,1,.36,1)'})}}))}
  function previewMove(targetId,pointerX){if(!draggedId||draggedId===targetId)return;const from=previewItems.findIndex(item=>item.id===draggedId),to=previewItems.findIndex(item=>item.id===targetId),targetBox=cardRefs.current.get(targetId)?.getBoundingClientRect();if(from<0||to<0||from===to||targetBox&&(from<to&&pointerX<targetBox.left+targetBox.width*.3||from>to&&pointerX>targetBox.left+targetBox.width/2))return;const before=cardPositions(),next=previewItems.slice(),[moved]=next.splice(from,1);next.splice(to,0,moved);setPreviewItems(next);animateCards(before,320,draggedId)}
  function buttonMove(index,direction){const target=index+direction;if(target<0||target>=displayed.length)return;const before=cardPositions();reorderFavorites(index,target);animateCards(before,650)}
  function moveDragGhost(event){if(!dragGhost.current||!event.clientX&&!event.clientY)return;dragGhost.current.style.left=`${event.clientX-dragOffset.current.x}px`;dragGhost.current.style.top=`${event.clientY-dragOffset.current.y}px`}
  function finishDrag(save=true){if(save&&dragOrigin.current!==null&&draggedId){const target=previewItems.findIndex(item=>item.id===draggedId);if(target>=0&&target!==dragOrigin.current)reorderFavorites(dragOrigin.current,target)}dragGhost.current?.remove();dragGhost.current=null;dragOrigin.current=null;setDraggedId(null)}
  const displayed=isMyList?previewItems:items
  return <section className="shelf"><h2>{title}</h2>{edges.end&&!edges.start&&<span aria-hidden="true" className="shelf-arrow shelf-arrow-left"><FontAwesomeIcon icon={faChevronLeft}/></span>}<div className={title==='Latest Added'?'shelf-track latest-added-track':'shelf-track'} ref={track}>{displayed.map((item,index)=><MediaCard key={item.id} item={item} position={positions.get(item.id)} favorite={favorites.has(item.id)} toggleFavorite={toggleFavorite} play={play} reorder={isMyList?{index,total:displayed.length,move:direction=>buttonMove(index,direction)}:null} dragging={draggedId===item.id} cardRef={isMyList?node=>{if(node)cardRefs.current.set(item.id,node);else cardRefs.current.delete(item.id)}:undefined} dragProps={isMyList?{draggable:true,onDragStart:event=>{event.dataTransfer.effectAllowed='move';const ghost=event.currentTarget.cloneNode(true),box=event.currentTarget.getBoundingClientRect(),offsetX=event.clientX-box.left,offsetY=event.clientY-box.top,blank=document.createElement('canvas');blank.width=blank.height=1;event.dataTransfer.setDragImage(blank,0,0);dragOffset.current={x:offsetX,y:offsetY};ghost.classList.remove('dragging');ghost.style.cssText=`position:fixed;z-index:10000;pointer-events:none;left:${event.clientX-offsetX}px;top:${event.clientY-offsetY}px;width:${box.width}px;opacity:1;transform:scale(1.09) rotate(-1deg);transform-origin:${offsetX}px ${offsetY}px;border:2px solid #e7ad35;box-shadow:0 24px 55px #000e;filter:brightness(1.05);`;document.body.appendChild(ghost);dragGhost.current=ghost;dragOrigin.current=items.findIndex(entry=>entry.id===item.id);setPreviewItems(items);setDraggedId(item.id)},onDrag:moveDragGhost,onDragEnd:()=>finishDrag(false),onDragEnter:event=>previewMove(item.id,event.clientX),onDragOver:event=>{event.preventDefault();event.dataTransfer.dropEffect='move';moveDragGhost(event)},onDrop:event=>{event.preventDefault();finishDrag(true)}}:undefined}/>)}{title==='Continue Watching'&&!items.length&&<div className="empty-row-card">Nothing here yet</div>}{isMyList&&<button className="empty-list-button" onClick={onEmptyMyList}><span><FontAwesomeIcon icon={faPlus}/></span>Add to My List</button>}</div>{edges.start&&!edges.end&&<span aria-hidden="true" className="shelf-arrow shelf-arrow-right"><FontAwesomeIcon icon={faChevronRight}/></span>}</section>
}

function ManageVideos({request,save,saveSeries,onDone}){
  const[query,setQuery]=useState(''),[rating,setRating]=useState(''),[items,setItems]=useState([]),[editing,setEditing]=useState(null),[expanded,setExpanded]=useState(null),[loading,setLoading]=useState(true),[saving,setSaving]=useState(false),[message,setMessage]=useState('')
  useEffect(()=>{
    let active=true
    const timer=setTimeout(async()=>{
      setMessage('')
      try{const results=await request(`/api/manage-media?q=${encodeURIComponent(query)}&rating=${encodeURIComponent(rating)}&limit=500`);if(active)setItems(results)}catch(error){if(active)setMessage(error.message)}finally{if(active)setLoading(false)}
    },query?250:0)
    return()=>{active=false;clearTimeout(timer)}
  },[query,rating])
  const groups=useMemo(()=>{const series=new Map(),result=[];for(const item of items){if(!item.seriesId){result.push(item);continue}const group=series.get(item.seriesId)||{seriesId:item.seriesId,title:item.seriesTitle,episodes:[]};group.episodes.push(item);series.set(item.seriesId,group)}for(const group of series.values()){group.episodes.sort((a,b)=>(a.seasonNumber||0)-(b.seasonNumber||0)||(a.episodeNumber||0)-(b.episodeNumber||0));const first=group.episodes[0];result.push({...group,thumbnailUrl:first.thumbnailUrl,rating:first.rating||'',genres:first.genres||[],blocked:first.blocked,minAge:first.minAge||0,mixed:group.episodes.some(item=>item.rating!==first.rating||item.blocked!==first.blocked||item.minAge!==first.minAge||JSON.stringify(item.genres)!==JSON.stringify(first.genres))})}return result.sort((a,b)=>a.title.localeCompare(b.title))},[items])
  function edit(item,mode='episode'){setMessage('');setEditing({...item,mode,rating:item.rating||'',genres:item.genres||[]})}
  function toggleGenre(genre){setEditing(current=>({...current,genres:current.genres.includes(genre)?current.genres.filter(item=>item!==genre):[...current.genres,genre]}))}
  async function submit(event){event.preventDefault();try{setSaving(true);setMessage('');const settings={rating:editing.rating,blocked:editing.blocked,minAge:Number(editing.minAge||0),genres:editing.genres};if(editing.mode==='series'){const updated=await saveSeries(editing.seriesId,settings);setItems(current=>current.map(item=>item.seriesId===editing.seriesId?{...item,...settings}:item));setMessage(`Settings applied to ${updated.updatedEpisodes} episodes.`)}else{const updated=await save(editing.id,{...settings,title:editing.title,description:editing.description});setItems(current=>current.map(item=>item.id===editing.id?{...item,...updated}:item));setMessage('Video saved.')}setEditing(null)}catch(error){if(error?.name!=='ClerkRuntimeError')setMessage(error.message||'Password verification was cancelled.')}finally{setSaving(false)}}
  return <section className="manage-videos"><header><div><small>Library administration</small><h2>Manage Videos</h2></div><button className="primary-button" onClick={onDone}>Done</button></header><div className="manage-video-search"><FontAwesomeIcon icon={faMagnifyingGlass}/><input autoFocus value={query} onChange={event=>setQuery(event.target.value)} placeholder="Search titles or series" aria-label="Search videos"/><label className="manage-rating-filter">Rating<select value={rating} onChange={event=>setRating(event.target.value)}><option value="">All ratings</option>{['G','PG','PG-13','R','NC-17','TV-Y','TV-Y7','TV-G','TV-PG','TV-14','TV-MA','NR'].map(value=><option key={value} value={value}>{value}</option>)}<option value="missing">Missing rating</option></select></label></div>{message&&<p className="manage-message" role="status">{message}</p>}{editing?<form className="video-editor" onSubmit={submit}><button className="series-back icon-button" type="button" onClick={()=>{setEditing(null);setMessage('')}}><FontAwesomeIcon icon={faArrowLeft}/>Back to results</button><div className="video-editor-heading">{editing.thumbnailUrl&&<img src={editing.thumbnailUrl} alt=""/>}<div><small>{editing.seriesTitle?`${editing.seriesTitle}${editing.seasonNumber?` · Season ${editing.seasonNumber}`:''}${editing.episodeNumber?` · Episode ${editing.episodeNumber}`:''}`:editing.category}</small><h3>{editing.title}</h3></div></div>{editing.mode==="series"?<p className="series-settings-note">These settings apply to every episode. Edit an individual episode afterward to override its age or other access settings.</p>:<><label>Title<input required maxLength="200" value={editing.title} onChange={event=>setEditing(current=>({...current,title:event.target.value}))}/></label><label>Description<textarea rows="6" maxLength="4000" value={editing.description||''} onChange={event=>setEditing(current=>({...current,description:event.target.value}))}/></label></>}<label>Rating<select value={editing.rating} onChange={event=>setEditing(current=>({...current,rating:event.target.value}))}><option value="">Unrated</option>{['G','PG','PG-13','R','NC-17','TV-Y','TV-Y7','TV-G','TV-PG','TV-14','TV-MA'].map(rating=><option key={rating}>{rating}</option>)}</select></label><label>Age Available<input type="number" min="0" max="21" step="1" required value={editing.minAge??0} onChange={event=>setEditing(current=>({...current,minAge:event.target.value}))}/><small>Use 0 for all ages. The title stays hidden until the profile reaches this age.</small></label><fieldset><legend>Genres</legend><div className="genre-editor">{genres.map(genre=><button type="button" key={genre} className={editing.genres.includes(genre)?'selected':''} onClick={()=>toggleGenre(genre)} aria-pressed={editing.genres.includes(genre)}>{genre}</button>)}</div></fieldset><label className="toggle-row blocked-toggle"><span><strong>Blocked</strong><small>Hide this title from every profile until you unblock it.</small></span><input type="checkbox" checked={editing.blocked} onChange={event=>setEditing(current=>({...current,blocked:event.target.checked}))}/></label><div className="form-actions"><button className="primary-button" type="submit" disabled={saving}>{saving?'Saving...':editing.mode==='series'?'Apply to All Episodes':'Save Video'}</button><button type="button" onClick={()=>setEditing(null)} disabled={saving}>Cancel</button></div></form>:loading?<LoadingScreen/>:<div className="manage-video-list">{groups.map(item=>item.episodes?<article className="manage-series-card" key={item.seriesId}><button className={"manage-video-card"+(item.blocked?" blocked":"")} onClick={()=>edit(item,"series")}>{item.thumbnailUrl?<img src={item.thumbnailUrl} alt=""/>:<span className="poster-placeholder"><FontAwesomeIcon icon={faVideo}/></span>}<span><strong>{item.title}</strong><small>{item.episodes.length+" episodes · "+(item.minAge?"Age "+item.minAge+"+":"All ages")}</small>{item.mixed&&<b>Individual episode settings</b>}{item.blocked&&<b><FontAwesomeIcon icon={faLock}/> Blocked</b>}</span><FontAwesomeIcon className="manage-edit-icon" icon={faPen}/></button><button className="episode-toggle" type="button" onClick={()=>setExpanded(value=>value===item.seriesId?null:item.seriesId)}>{expanded===item.seriesId?"Hide Individual Episodes":"Edit Individual Episodes"}</button>{expanded===item.seriesId&&<div className="series-episode-list">{item.episodes.map(episode=><button type="button" key={episode.id} onClick={()=>edit(episode)}><span><strong>{"S"+(episode.seasonNumber||0)+" E"+(episode.episodeNumber||0)+" · "+episode.title}</strong><small>{episode.minAge?"Age "+episode.minAge+"+":"All ages"}{episode.blocked?" · Blocked":""}</small></span><FontAwesomeIcon icon={faPen}/></button>)}</div>}</article>:<button key={item.id} className={"manage-video-card"+(item.blocked?" blocked":"")} onClick={()=>edit(item)}>{item.thumbnailUrl?<img src={item.thumbnailUrl} alt=""/>:<span className="poster-placeholder"><FontAwesomeIcon icon={faVideo}/></span>}<span><strong>{item.title}</strong><small>{item.minAge?"Age "+item.minAge+"+":"All ages"}</small>{item.blocked&&<b><FontAwesomeIcon icon={faLock}/> Blocked</b>}</span><FontAwesomeIcon className="manage-edit-icon" icon={faPen}/></button>)}</div>}</section>
}

function PicturePicker({value,setValue,profileName,onSave,onCancel,busy}){const selected=legacyProfilePictures[value]||value;return <div className="modal-backdrop"><div className="dialog picture-dialog" role="dialog" aria-modal="true" aria-labelledby="picture-title"><h3 id="picture-title">Choose {profileName?`${profileName}'s `:''}profile picture</h3><div className="avatar-picker">{profilePictureGroups.map(([group,pictures])=><section className="avatar-picker-group" key={group}><h4>{group}</h4><div className="avatar-picker-grid">{pictures.map(picture=>{const character=picture.split('--')[1].replace(/\.[^.]+$/,'').replaceAll('-',' ');return <button key={picture} type="button" className={selected===picture?'selected':''} onClick={()=>setValue(picture)} aria-label={`Use ${character} from ${group} as profile picture`} aria-pressed={selected===picture}><img src={profilePicture(picture)} alt=""/>{selected===picture&&<FontAwesomeIcon icon={faCheck}/>}</button>})}</div></section>)}</div><div className="form-actions"><button className="primary-button" type="button" onClick={onSave} disabled={busy}>{busy?'Saving...':'Use Picture'}</button><button type="button" onClick={onCancel} disabled={busy}>Cancel</button></div></div></div>}
function PinDialog({profile,pin,setPin,busy,submit,cancel}){const input=React.useRef(null),[viewport,setViewport]=useState(()=>({height:window.visualViewport?.height||window.innerHeight,top:window.visualViewport?.offsetTop||0}));useEffect(()=>{const visual=window.visualViewport;if(!visual)return;const update=()=>setViewport({height:visual.height,top:visual.offsetTop});update();visual.addEventListener('resize',update);visual.addEventListener('scroll',update);return()=>{visual.removeEventListener('resize',update);visual.removeEventListener('scroll',update)}},[]);function change(event){const next=event.target.value.replace(/\D/g,'').slice(0,4);setPin(next);if(next.length===4&&!busy)submit(next)}return <div className="modal-backdrop pin-backdrop" style={{height:`${viewport.height}px`,top:`${viewport.top}px`,bottom:'auto'}}><section className="pin-dialog" role="dialog" aria-modal="true" aria-labelledby="pin-title" onClick={()=>input.current?.focus()}><button className="pin-close" type="button" onClick={event=>{event.stopPropagation();cancel()}} aria-label="Cancel PIN entry"><FontAwesomeIcon icon={faXmark}/></button><p>Profile Lock is currently on.</p><h2 id="pin-title">Enter your PIN to access {profile.name}.</h2><div className="pin-boxes">{[0,1,2,3].map(index=><span aria-hidden="true" className={pin.length===index?'active':''} key={index}>{pin[index]?'•':''}</span>)}<input ref={input} className="pin-hidden-input" autoFocus inputMode="numeric" enterKeyHint="done" autoComplete="off" type="text" maxLength="4" pattern="[0-9]*" value={pin} disabled={busy} onChange={change} aria-label="Four digit PIN"/></div></section></div>}
function ProfileForm({title,form,setForm,onSubmit,onCancel,onDelete,onChooseAvatar,hasPin=false,busy}){const[confirmDelete,setConfirmDelete]=useState(false);const change=values=>setForm(current=>({...current,...values}));return <form className="profile-form" onSubmit={onSubmit}><h2>{title}</h2><div className="profile-picture-field"><Avatar profile={{id:'profile-preview',avatar:form.avatar}}/><div><strong>Profile picture</strong><button className="outline-button icon-button" type="button" onClick={onChooseAvatar}><FontAwesomeIcon icon={faCamera}/>Choose Picture</button></div></div><label>Profile name<input autoFocus maxLength="40" required value={form.name} onChange={e=>change({name:e.target.value})}/></label><label>Date of birth<input type="date" required min="1900-01-01" max={localDateInputValue()} value={form.dateOfBirth} onChange={e=>change({dateOfBirth:e.target.value})}/><small>Used only to automatically unlock age-appropriate videos.</small></label><label className="check"><input type="checkbox" checked={form.homeVideosOnly} onChange={e=>change({homeVideosOnly:e.target.checked})}/><span><strong>Home videos only</strong><small>This profile can only browse and watch home videos.</small></span></label><label><FontAwesomeIcon icon={faLock}/> {hasPin?'New PIN':'Optional PIN'}<input className="pin-input" inputMode="numeric" enterKeyHint="done" autoComplete="new-password" type="password" minLength="4" maxLength="4" pattern="[0-9]{4}" value={form.pin} disabled={form.removePin} onChange={e=>change({pin:e.target.value.replace(/\D/g,'').slice(0,4)})} placeholder={hasPin?'Leave blank to keep current PIN':'Four digits'}/></label>{hasPin&&<label className="check"><input type="checkbox" checked={form.removePin} onChange={e=>change({removePin:e.target.checked,pin:''})}/><span><strong><FontAwesomeIcon icon={faXmark}/> Remove PIN</strong><small>Anyone using this account will be able to open the profile.</small></span></label>}<div className="form-actions"><button className="primary-button" type="submit" disabled={busy}>{busy?'Saving...':'Save'}</button><button type="button" onClick={onCancel}>Cancel</button>{onDelete&&<button className="danger-button icon-button" type="button" onClick={()=>setConfirmDelete(true)} disabled={busy}><FontAwesomeIcon icon={faTrashCan}/>Delete Profile</button>}</div>{confirmDelete&&<div className="modal-backdrop"><div className="dialog confirm-dialog" role="alertdialog" aria-modal="true" aria-labelledby="delete-title"><FontAwesomeIcon className="warning-icon" icon={faTriangleExclamation}/><h3 id="delete-title">Are you sure?</h3><p>Delete <strong>{form.name}</strong>? This will permanently delete the profile and its viewing progress.</p><div className="form-actions"><button type="button" onClick={()=>setConfirmDelete(false)} autoFocus>Cancel</button><button className="danger-button icon-button" type="button" onClick={onDelete} disabled={busy}><FontAwesomeIcon icon={faTrashCan}/>{busy?'Deleting...':'Delete Profile'}</button></div></div></div>}</form>}
const appUrl=`${window.location.origin}${import.meta.env.BASE_URL}`
createRoot(document.getElementById('root')).render(key&&api?<ClerkProvider publishableKey={key}><SignedOut><main className="signed-out"><Logo/><p>Your private video library.</p><SignIn routing="hash" fallbackRedirectUrl={appUrl}/></main></SignedOut><SignedIn><App/></SignedIn></ClerkProvider>:<main className="signed-out"><Logo/><p>Set VITE_CLERK_PUBLISHABLE_KEY and VITE_API_URL to configure this app.</p></main>)
